"""A Class for performing sequenced interactions to login in on a MOSAIQ application"""

from ..interactions import MosaiqLogin

class Login():
    def __init__(self) -> None:
        pass

    def loginUser(self, username: str, password: str) -> None:
        MosaiqLogin.enter_username(username)
        MosaiqLogin.enter_password(password)
        MosaiqLogin.click_login_button()
        if MosaiqLogin.confirm_sucessful_login(30000):
            print("Logged in")
